        SELECT 
        FROM `dish`

            is_deleted = 0

                AND (
dish_name LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR dish_no LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR description LIKE CONCAT('%', #{query.searchKeyword}, '%')
                )

            AND dish_name LIKE CONCAT('%', #{query.dishName}, '%')
            AND dish_no LIKE CONCAT('%', #{query.dishNo}, '%')
            AND image LIKE CONCAT('%', #{query.image}, '%')
            AND description LIKE CONCAT('%', #{query.description}, '%')
            AND unit LIKE CONCAT('%', #{query.unit}, '%')
            AND store_id = #{query.storeId}
            AND category_id = #{query.categoryId}
            AND taste_id = #{query.tasteId}
            AND spec_id = #{query.specId}
            AND is_recommend = #{query.isRecommend}
            AND is_new = #{query.isNew}
            AND is_sold_out = #{query.isSoldOut}
            AND sale_count = #{query.saleCount}
            AND sort = #{query.sort}
            AND status = #{query.status}
            AND create_time >= CONCAT(#{query.searchBeginTime}, ' 00:00:00')
            AND create_time <= CONCAT(#{query.searchEndTime}, ' 23:59:59')

        ORDER BY id DESC

mapper.update:
UPDATE `dish`
store_id = #{storeId}, category_id = #{categoryId}, dish_name = #{dishName}, dish_no = #{dishNo}, image = #{image}, description = #{description}, price = #{price}, origin_price = #{originPrice}, unit = #{unit}, taste_id = #{tasteId}, spec_id = #{specId}, is_recommend = #{isRecommend}, is_new = #{isNew}, is_sold_out = #{isSoldOut}, sale_count = #{saleCount}, sort = #{sort}, status = #{status}, create_time = #{createTime}, update_time = #{updateTime}, is_deleted = #{isDeleted},
WHERE id = #{id}
